edit_instructions.target_text:
-- Clean a set of polygons that should form a seamless coverage
-- Fixes: overlaps, gaps, edge inconsistencies
SELECT ST_CoverageClean(
  ARRAY[polygon1, polygon2, polygon3]::geometry[]
) AS cleaned_polygons;

edit_instructions.replacement_text:
-- Validate individual polygon geometries (fixes self-intersections)
-- Does NOT fix coverage errors like overlaps or gaps
SELECT ST_MakeValid(geom) AS valid_geom FROM municipalities;

edit_instructions.target_text:
-- Example: Clean municipal boundaries
WITH boundaries AS (
  SELECT geom FROM municipalities
)
SELECT ST_CoverageClean(array_agg(geom))
FROM boundaries;

